import{z as s,x as r,o as A,c as d,q as i,j as t,D as e,d as B,s as l,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"事故指挥","description":"","frontmatter":{"title":"事故指挥","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/obs-incident-command.md","filePath":"cs/obs-incident-command.md","lastUpdated":1791063341000}'),C={name:"cs/obs-incident-command.md"};function p(D,E,m,c,F,h){const n=r("Mermaid");return A(),d("div",null,[E[2]||(E[2]=i('<h1 id="事故指挥" tabindex="-1">事故指挥 <a class="header-anchor" href="#事故指挥" aria-label="Permalink to &quot;事故指挥&quot;">​</a></h1><div class="epigraph"><p>事故里最稀缺的不是算力是注意力：指挥的存在，是让修机器的人不必同时回答老板、用户和律师。</p><footer>—— 据 Google SRE 书第 14 章 Managing Incidents；事故指挥体系（ICS）源于野火消防的分层指挥整理</footer></div><p><a href="/cs/obs-slo-engineering">上一课</a>的烧速告警响了：预算在以十四倍速消耗，呼人策略已经触发。缺口是告警之后的组织行为——谁决策、谁动手、谁沟通、谁记录。安全事件有 <a href="/cs/incident-response">事件响应</a>的生命周期，那是安全口径，证据保全优先。本课写可用性事故的指挥结构：角色分离、严重度分级、止损决策、沟通节奏。它与<a href="/cs/chaos-engineering">混沌工程</a>共享 SLO 测量面，只是混沌主动注入、事故被动到来。后课复盘默认已读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有指挥结构的事故现场是固定剧目：最懂系统的工程师埋头修，单点知识被锁在键盘前；事后没人说得清时间线。指挥要回答的工程问题只有一个：在不完全信息下，如何分配修复、沟通、记录三种注意力，使止损最快且不制造新事故。严重度分级是响应配置的选择器：SEV1 唤醒整个指挥结构加对外沟通，SEV3 一张工单即可——级别不是事故的固有属性，是「投入多少注意力」的决策，而决策标准来自上一课的影响面与预算消耗。</p><h3 id="角色分离" tabindex="-1">角色分离 <a class="header-anchor" href="#角色分离" aria-label="Permalink to &quot;角色分离&quot;">​</a></h3><p>指挥（IC）不操作，只决策与协调：比较止损方案、宣布状态、砍掉「再试五分钟」、决定升级。操作负责人动手：回滚、切流量、扩容。沟通负责人按固定节奏向内外发更新。记录者实时写时间线，为下一课复盘供料。小团队可以把角色合并到两个人，但「决策、操作、沟通」三种注意力必须有人在管——合并的是人头，不是职能。</p>',7)),(A(),t(o,null,{default:e(()=>[l(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALERT%5B%22%E7%83%A7%E9%80%9F%E5%91%8A%E8%AD%A6%22%5D%20--%3E%20OPS%5B%22%E5%80%BC%E7%8F%AD%E8%AF%95%E4%BF%AE%EF%BC%8C%E9%99%90%E6%97%B6%E5%8D%87%E7%BA%A7%22%5D%0A%20%20OPS%20--%3E%20IC%5B%22%E4%BB%BB%E5%91%BD%E6%8C%87%E6%8C%A5%EF%BC%8C%E5%AE%9A%E4%B8%A5%E9%87%8D%E5%BA%A6%22%5D%0A%20%20IC%20--%3E%20MIT%5B%22%E6%AD%A2%E6%8D%9F%EF%BC%9A%E5%9B%9E%E6%BB%9A%20%2F%20%E9%99%8D%E7%BA%A7%20%2F%20%E5%88%87%E6%B5%81%20%2F%20%E6%89%A9%E5%AE%B9%22%5D%0A%20%20IC%20--%3E%20CL%5B%22%E8%8A%82%E5%A5%8F%E5%8C%96%E5%86%85%E5%A4%96%E6%B2%9F%E9%80%9A%22%5D%0A%20%20IC%20--%3E%20SCR%5B%22%E5%AE%9E%E6%97%B6%E6%97%B6%E9%97%B4%E7%BA%BF%22%5D%0A%20%20MIT%20--%3E%20STABLE%5B%22%E6%8C%87%E6%A0%87%E5%9B%9E%E7%A8%B3%EF%BC%8C%E8%A7%82%E5%AF%9F%E6%9C%9F%22%5D%0A%20%20STABLE%20--%3E%20FIX%5B%22%E5%86%8D%E4%BF%AE%E6%A0%B9%E5%9B%A0%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"大多数事故往前数 24 小时内能找到变更：部署、配置、流量结构。止损的第一反应不是推理，是回看变更列表——「最近改了什么」比「为什么坏」便宜得多。")],-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"常见误区：初学者容易以为严重度是事故的固有属性——「这事故本身就是 SEV1」。实际上级别是对「投入多少响应注意力」的决策：同一次故障，发生在周五晚高峰和周二凌晨，定级可以完全不同。")],-1)),E[5]||(E[5]=a("h2",{id:"方法",tabindex:"-1"},[B("方法 "),a("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[6]||(E[6]=a("p",null,"升级路径先钉死：值班操作员试修，限时——比如十五分钟无进展就拉指挥，指挥视影响面升级严重度并唤醒角色。止损优先于根因：四个标准止损钮按可逆性与速度排——回滚到上一版本、降级关闭非核心功能、切走流量、扩容稀释压力；先按最快可逆的那个，bug 的根因分析在止血之后。指挥的决策纪律：两个假设都未证实时，选止损覆盖面大的；止损动作必须可宣布、可撤销，避免用新事故盖旧事故。沟通的模板四件套：现状、影响面、下一步、下次更新时间，按固定间隔发，哪怕内容是「仍在调查」——沉默比坏消息贵。记录与操作并行：时间线要记的不是事件流水，是每一步「当时知道什么、据此做了什么」。",-1)),(A(),t(o,null,{default:e(()=>[l(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E7%A1%AE%E8%AE%A4%E4%BA%8B%E6%95%85%22%5D%20--%3E%20CHG%7B%22%E6%9C%80%E8%BF%91%2024%20%E5%B0%8F%E6%97%B6%E6%94%B9%E4%BA%86%E4%BB%80%E4%B9%88%22%7D%0A%20%20CHG%20--%3E%7C%22%E6%9C%89%E5%8F%AF%E7%96%91%E5%8F%98%E6%9B%B4%22%7C%20RB%5B%22%E5%9B%9E%E6%BB%9A%E4%B8%8A%E4%B8%80%E7%89%88%E6%9C%AC%20%E6%9C%80%E5%BF%AB%E5%8F%AF%E9%80%86%22%5D%0A%20%20CHG%20--%3E%7C%22%E6%97%A0%E5%8F%98%E6%9B%B4%E5%8F%AF%E5%BD%92%E5%9B%A0%22%7C%20DG%7B%22%E8%83%BD%E5%90%A6%E5%B1%80%E9%83%A8%E9%9A%94%E7%A6%BB%22%7D%0A%20%20DG%20--%3E%7C%22%E8%83%BD%22%7C%20DE%5B%22%E9%99%8D%E7%BA%A7%E6%88%96%E5%88%87%E8%B5%B0%E6%B5%81%E9%87%8F%22%5D%0A%20%20DG%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20SC%5B%22%E6%89%A9%E5%AE%B9%E7%A8%80%E9%87%8A%E5%8E%8B%E5%8A%9B%22%5D%0A%20%20RB%20--%3E%20MON%5B%22%E5%AE%A3%E5%B8%83%E5%8A%A8%E4%BD%9C%20%E8%A7%82%E5%AF%9F%E6%8C%87%E6%A0%87%22%5D%0A%20%20DE%20--%3E%20MON%0A%20%20SC%20--%3E%20MON%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=i('<p><span class="marginnote">数字实例：「限时升级」就是给沉没成本划死线：14:00 告警、14:15 无进展就拉指挥——不论操作员「马上就要修好了」的感觉多强烈。没有这条死线，「再试五分钟」可以吃掉一整晚。</span></p><p><span class="marginnote">直觉类比：事故指挥像急诊室——IC 是值班主治医生，不亲自缝合伤口，只决定先救谁、用哪个方案；护士动手，家属谈话专人负责。让医生边缝合边答家属问，两头都会砸。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么指挥不操作：操作占满工作记忆，决策与操作同一人时，沉没成本没人砍，「再试五分钟」会吃掉整晚；IC 的产出是让止损方案在最短时间内被摆上桌、被比较、被选择。为什么节奏化沟通有效：利益相关者的打断频率与沟通频率成反比——更新发得准点，冲进来问「好了没」的人就少。为什么时间线要实时记：事后回忆会把「我们当时以为」改写成「我们当时知道」，复盘需要的是决策时的信息状态，这是记录者独立于操作者的理由。为什么止损优先：每分钟宕机的损失通常远大于根因提前一小时的收益，而可逆的止损风险低——这条偏好要有组织背书，否则操作员会被「查清再动」的文化捆住手脚。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写安全事件的生命周期：证据链、法律保留、反制禁区是事件响应课的口径，两套流程在「准备」阶段就该分开写预案。值班排班、补偿与团队规模是组织课题，不展开。指挥结构不是规模上的普适：小事故两个人也能跑完角色职能；系统与团队变大时，把职能并进同一个人头才是要避免的。止损成功不是终点——事故此刻还只是损失，下一课把它变成组织资产。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>事故指挥分配三种注意力：修复、沟通、记录，职能可并人头不可并。</li><li>严重度是响应配置的选择器，标准来自影响面与预算消耗。</li><li>止损优先于根因：回滚、降级、切流、扩容，先按最快可逆的钮。</li><li>固定节奏加四件套模板，沉默比坏消息贵。</li><li>时间线实时记决策时的信息状态，为复盘供料。</li><li>出处：Google SRE 书第 14 章；ICS 源于野火消防的分层指挥；安全口径见 NIST SP 800-61 与事件响应课。</li></ul>',8))])}const f=s(C,[["render",p]]);export{S as __pageData,f as default};
